#pragma once

// unicode property tables.
// the definitions in unicodedata.c are generated by tools/unicodedata.py.
// every table is sorted by code point so it can be binary searched.
#include "types.h"

enum GraphemeBreak {
  GraphemeBreakOther,
  GraphemeBreakCr,
  GraphemeBreakLf,
  GraphemeBreakControl,
  GraphemeBreakExtend,
  GraphemeBreakZwj,
  GraphemeBreakRegionalIndicator,
  GraphemeBreakPrepend,
  GraphemeBreakSpacingMark,
  GraphemeBreakL,
  GraphemeBreakV,
  GraphemeBreakT,
  GraphemeBreakLv,
  GraphemeBreakLvt
};

// an inclusive run of code points sharing one property value.
typedef struct UnicodeRange {
  u32 first;
  u32 last;
  u8 value;
} UnicodeRange;

// a simple (one to one) case folding.
typedef struct UnicodeFold {
  u32 from;
  u32 to;
} UnicodeFold;

// unicode version the tables were generated from.
extern const char unicodeVersion[];

// display width 0 or 2.
// code points not listed are 1 column wide.
extern const UnicodeRange unicodeWidths[];
extern const u32 unicodeWidthCount;

// grapheme cluster break property as an enum GraphemeBreak value.
// code points not listed are GraphemeBreakOther.
extern const UnicodeRange unicodeGraphemeBreaks[];
extern const u32 unicodeGraphemeBreakCount;

// code points with the Extended_Pictographic property (value is unused).
extern const UnicodeRange unicodePictographics[];
extern const u32 unicodePictographicCount;

// simple case folding used for case insensitive search.
extern const UnicodeFold unicodeFolds[];
extern const u32 unicodeFoldCount;
